#!/usr/bin/env bun
/**
 * bin/emit-ast-validator.ts — eidos emits an ast-grep validator into a
 * scaffolded product (the r503-forge pattern from mcp-dropin-guide R-503).
 *
 * A product scaffolded by eidos gets:
 *   bin/sg/r503.ts.yml   — the ast-grep rule config for this product
 *   bin/ast-check.sh     — the machine gate: bun/ast-grep structural scan
 *
 * Usage: bun bin/emit-ast-validator.ts --target <dir>
 */
import { mkdirSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";

const argIdx = process.argv.indexOf("--target");
const target = argIdx !== -1 ? process.argv[argIdx + 1] : null;
if (!target) { console.error("usage: bun bin/emit-ast-validator.ts --target <dir>"); process.exit(1); }
if (!existsSync(join(target, "package.json"))) { console.error(`no package.json at ${target}`); process.exit(2); }

mkdirSync(join(target, "bin", "sg"), { recursive: true });

// The R-503 rule: forbid process.cwd() reads (hephaistos contract doctrine:
// ctx only — the host resolves everything). Structural, not text.
const rule = `id: r503-no-process-cwd
language: ts
severity: warning
message: "Do not read process.cwd() directly — the host resolves paths via ctx (eidos/hephaistos doctrine)."
rule:
  pattern: process.cwd()
`;

writeFileSync(join(target, "bin", "sg", "r503.ts.yml"), rule);

const check = `#!/usr/bin/env bash
# ast-grep structural gate (eidos-emitted, r503 pattern)
set -e
ROOT="\$(cd "\$(dirname "\${BASH_SOURCE[0]}")/.." && pwd)"
command -v ast-grep >/dev/null || { echo "ast-grep missing — bun x @ast-grep/cli"; exit 2; }
ast-grep scan "\$ROOT" --rule "\$ROOT/bin/sg/r503.ts.yml"
rc=\$?
[ \$rc -eq 0 ] && echo "[ast-check] PASS" || echo "[ast-check] FINDINGS above (exit \$rc)"
exit \$rc
`;
writeFileSync(join(target, "bin", "ast-check.sh"), check, { mode: 0o755 });

console.log(`eidos ast-validator emitted -> ${target}/bin/{sg/r503.ts.yml, ast-check.sh}`);

/**
 * agent-relaunch-lib-dropin.ts — daemon-aware agent discovery/diagnosis/relaunch
 * as an eidos drop-in library.
 *
 * Ground truth doctrine: docs lie, /proc wins (eidos AGENTS.md rule 6).
 * Discovery = pitchfork state + /proc cmdline sweep. Diagnosis = root-cause
 * classes mined from the Pens's anomaly program (#41 dir-ENOENT, #43 mise,
 * #5 front-door-vs-exec, #72 credit strikes, #48 ghost lease).
 *
 * USAGE:
 *   const rel = agentRelaunch();
 *   const daemons = await rel.discover();        // all pitchfork daemons, live
 *   const sick = daemons.value.filter(d => d.status !== "running");
 *   const diags  = await rel.diagnose(sick);     // root-cause each
 *   await rel.relaunch("geode/rhodochrosite");   // restart + health-verify
 */
import { existsSync, readFileSync, readdirSync, readlinkSync } from "node:fs";
import { ok, err, type Result } from "neverthrow";

export type DaemonStatus = "running" | "stopped" | "errored";

export interface Daemon {
	id: string;              // namespace/daemon-id (pitchfork form)
	status: DaemonStatus;
	pid?: number;
	port?: number;
	dir?: string;
	run?: string;
	/** true when relaunching is safe (retry daemons, non-critical) */
	safeRelaunch: boolean;
}

export type RootCause =
	| "ghost-path"
	| "port-conflict"
	| "binary-missing"
	| "config-error"
	| "probe-401-flap"
	| "unknown";

export interface Diagnosis {
	id: string;
	rootCause: RootCause;
	detail: string;
	fix: string;
}

const STATE_GLOB = "/home/toxic/.local/state/pitchfork/state.toml";

function readState(): Result<string, Error> {
	try {
		return ok(readFileSync(STATE_GLOB, "utf8"));
	} catch (e) {
		return err(e instanceof Error ? e : new Error(String(e)));
	}
}

/** Live /proc ground truth: is a pid with this daemon's marker actually running? */
function procAlive(marker: string): number | null {
	for (const pidDir of readdirSync("/proc").filter((d) => /^\d+$/.test(d))) {
		try {
			const cmd = readFileSync(`/proc/${pidDir}/cmdline`, "utf8").replace(/\0/g, " ");
			if (cmd.includes(marker) && !cmd.includes("grep") && !cmd.includes("log-sink")) {
				return Number(pidDir);
			}
		} catch {}
	}
	return null;
}

export function agentRelaunch() {
	return {
		id: "agent-relaunch-lib-dropin",
		version: "1.0.0",

		/** Discover every pitchfork daemon (state.toml + /proc). */
		async discover(): Promise<Result<Daemon[], Error>> {
			const state = readState();
			if (state.isErr()) return err(state.error);

			const daemons: Daemon[] = [];
			// parse [daemons."ns/id"] blocks
			const re = /\[daemons\."([^"]+)"\]([\s\S]*?)(?=\n\[|$)/g;
			let m: RegExpExecArray | null;
			while ((m = re.exec(state.value)) !== null) {
				const id = m[1]!;
				const block = m[2]!;
				const statusRaw = block.match(/status = "([^"]+)"/)?.[1] ?? "stopped";
				const status: DaemonStatus =
					statusRaw === "running" ? "running" : statusRaw === "errored" ? "errored" : "stopped";
				const run = block.match(/run = "([^"]+)"/)?.[1];
				const dir = block.match(/dir = "([^"]+)"/)?.[1];
				const portRaw = block.match(/port = (\d+)/)?.[1];
				const port = portRaw ? Number(portRaw) : undefined;

				// ground truth: a "stopped" daemon whose run marker is alive in /proc
				let pid: number | undefined;
				if (status === "running") {
					const marker = dir ?? run ?? "";
					if (marker) {
						const live = procAlive(marker.replace(/.*pens\//, "pens/"));
						pid = live ?? undefined;
						if (!live && status === "running") {
							// state lies — trust /proc
							daemons.push({ id, status: "stopped", port, dir, run, safeRelaunch: true });
							continue;
						}
					}
				}
				daemons.push({
					id, status, pid, port, dir, run,
					// relaunch-safe: retry-enabled infra lanes (routers, mcps, watch loops)
					safeRelaunch: /mcp|router|keepalive|watch|guard|bridge|keypool/.test(id),
				});
			}
			return ok(daemons);
		},

		/** Root-cause the sick daemons. */
		async diagnose(sick: Daemon[]): Promise<Result<Diagnosis[], Error>> {
			const out: Diagnosis[] = [];
			for (const d of sick.slice(0, 10)) {
				let rootCause: RootCause = "unknown";
				let detail = "";
				let fix = "restart via pitchfork";

				const run = d.run ?? "";
				if (run.includes("/home/toxic/pens/Pens/")) {
					rootCause = "ghost-path";
					detail = `run rooted at banned ghost: ${run.slice(0, 80)}`;
					fix = "repoint to /home/toxic/pens/Pens + restart";
				} else if (run.includes("mise ") ) {
					rootCause = "config-error";
					detail = "mise pre-spawn (anomaly #43 class)";
					fix = "drop mise=true, absolute binary path";
				} else if (d.port) {
					// port conflict: something else holds the port
					try {
						const ss = Bun.spawnSync(["ss", "-tlnp"], { stdout: "pipe" });
						const ssOut = Buffer.from(ss.stdout).toString();
						if (ssOut.includes(`:${d.port} `)) {
							rootCause = "port-conflict";
							detail = `port ${d.port} held by another process`;
							fix = "kill stale holder or repoint port (ports.env SSOT)";
						}
					} catch {}
				}
				if (rootCause === "unknown" && d.dir && !existsSync(d.dir)) {
					rootCause = "binary-missing";
					detail = `dir ENOENT: ${d.dir}`;
					fix = "re-clone/rebuild the def path (anomaly #70 class)";
				}
				out.push({ id: d.id, rootCause, detail: detail || d.status, fix });
			}
			return ok(out);
		},

		/** Relaunch + verify health. */
		async relaunch(id: string): Promise<Result<{ restarted: boolean; healthy: boolean }, Error>> {
			const p = Bun.spawnSync(["pitchfork", "restart", id], { stdout: "pipe", stderr: "pipe", timeout: 120_000 });
			const restarted = p.exitCode === 0;
			let healthy = restarted;
			// health: daemon reports running after settle
			if (restarted) {
				await Bun.sleep(3000);
				const st = Bun.spawnSync(["pitchfork", "status", id], { stdout: "pipe" });
				healthy = /running/i.test(Buffer.from(st.stdout).toString());
			}
			return ok({ restarted, healthy });
		},

		/**
		 * Queue-aware relaunch: when the lane is concurrency-limited (429
		 * concurrency_limit_exceeded — the Pens's most common inference stall),
		 * the relaunch QUEUES with backoff instead of hammering. The fallback
		 * chains must never retry-storm a limited lane.
		 */
		async relaunchWithQueue(
			id: string,
			opts: {
				isLimited?: () => boolean;
				queueDelayMs?: number;
				maxQueueAttempts?: number;
				/** injectable relaunch (tests); defaults to this.relaunch */
				relaunchFn?: (id: string) => Promise<Result<{ restarted: boolean; healthy: boolean }, Error>>;
			} = {},
		): Promise<
			Result<
				{ queued: boolean; queueAttempts: number; hammered: boolean; restarted: boolean; healthy: boolean },
				Error
			>
		> {
			const isLimited = opts.isLimited ?? (() => false);
			const queueDelayMs = opts.queueDelayMs ?? 1_000;
			const maxAttempts = opts.maxQueueAttempts ?? 5;

			// Queue semantics: backoff-wait while limited (linear), max N waits, then
			// attempt the relaunch REGARDLESS — a queued relaunch is one attempt with
			// patience, never a rapid retry-storm (that would be hammering).
			let queueAttempts = 0;
			while (isLimited() && queueAttempts < maxAttempts) {
				queueAttempts++;
				await Bun.sleep(queueDelayMs * queueAttempts); // linear backoff
			}
			const queued = queueAttempts > 0;
			const rel = await (opts.relaunchFn ?? ((i: string) => this.relaunch(i)))(id);
			if (rel.isErr()) return err(rel.error);
			// hammered = we blew past max attempts while still limited AND relaunch failed
			const hammered = queueAttempts >= maxAttempts && isLimited() && !rel.value.restarted;
			return ok({ queued, queueAttempts, hammered, ...rel.value });
		},
	};
}

/**
 * borrow-dropin.ts — BORROW the Pens's proven MCP drop-in wiring pattern
 * (from Pens-mcp-dropin-ship / mcp-dropin-guide) into eidos.
 *
 * The Pens already SHIPS drop-ins the same way every time — that IS the
 * pattern, and it lives in:
 *   - managed skill `Pens-mcp-dropin-ship` (SSOT: Pens/docs/mcp-guide-thresher.md)
 *   - `mcp-dropin-guide` R-3xx (thresher mcp_config.json registration)
 *   - the 27 parented products' bunfigs + the 132 infra services in ports.env
 *
 * This borrows that exact sequence into a callable function so a NEW product
 * scaffolded by eidos gets the drop-in wiring EMITTED, not hand-done:
 *
 *   1. ports.env         <NAME>_PORT=<free-25xxx> + owner comment
 *   2. pitchfork.toml    [daemons."<name>-mcp"] (monolith, auto=start, retry)
 *   3. thresher config   mcp_config.json http entry
 *   4. bunfig [env]      BUN_<NAME>_PORT from discoverDropins
 *
 * This is a GENERATOR (dry-run by default): it prints the exact blocks to
 * append. Use --write to apply. Never edits pitchfork.d fragments (dead).
 */
import { discoverDropins } from "../src/scaffold-services.ts";

export interface DropinSpec {
  name: string;        // e.g. "flotilla" → flotilla-mcp
  port?: number;       // resolved from ports.env if known, else free suggestion
  run: string;         // the exec command (bun <server>)
  mcpPath?: string;    // default "/mcp"
}

const PORTS_ENV = "/home/toxic/pens/Pens/config/ports.env";
const PITCHFORK = "/home/toxic/pens/Pens/pitchfork.toml";
// live thresher config — the Pens clone, NOT the stale ranch mirror
const THRESHER = "/home/toxic/pens/Pens/ranch/thresher/mcp_config.json";

/** Next free port suggestion in the Pens 25xxx range. */
export function suggestFreePort(existing: number[] = []): number {
  const used = new Set(existing);
  for (let p = 25200; p < 25299; p++) if (!used.has(p)) return p;
  return 25999;
}

/** Borrowed ports.env stanza (R-301 owner-comment convention). */
export function portsEnvBlock(spec: DropinSpec): string {
  return `# owner: ${spec.name} (${spec.name}-mcp drop-in via eidos)\n${spec.name.toUpperCase()}_PORT=${spec.port}\n`;
}

/** Borrowed pitchfork monolith daemon stanza (dashes, auto=start, retry). */
export function pitchforkBlock(spec: DropinSpec): string {
  return [
    "",
    `[daemons."${spec.name}-mcp"]`,
    `run = "${spec.run}"`,
    'auto = ["start"]',
    "retry = true",
    "mise = true",
    `port = ${spec.port}`,
    `ready_http = "http://127.0.0.1:${spec.port}${spec.mcpPath ?? "/mcp"}"`,
    "",
  ].join("\n");
}

/** Borrowed thresher mcp_config.json http entry (copy-an-existing verbatim rule). */
export function thresherBlock(spec: DropinSpec): string {
  return `{
  "name": "${spec.name}-mcp",
  "command": "${spec.run}",
  "protocol": "http",
  "url": "http://127.0.0.1:${spec.port}${spec.mcpPath ?? "/mcp"}",
  "enabled": true,
  "timeout": 30
}`;
}

/** Full borrowed drop-in plan for one product. */
export function borrowDropinPlan(spec: DropinSpec): {
  portsEnv: string; pitchfork: string; thresher: string; envVars: string[];
} {
  const dropins = discoverDropins();
  const port = spec.port ?? suggestFreePort(dropins.map((d) => d.port));
  const envVars = dropins
    .filter((d) => d.id === spec.name.toLowerCase())
    .map((d) => `${d.envVar}=${d.port}`);
  return {
    portsEnv: portsEnvBlock({ ...spec, port }),
    pitchfork: pitchforkBlock({ ...spec, port }),
    thresher: thresherBlock({ ...spec, port }),
    envVars,
  };
}

const version = "1.0.0-borrow-dropin";

export { version, PORTS_ENV, PITCHFORK, THRESHER };

/**
 * dropin/hephaistos.ts — eidos product hosting a hephaistos MCP server.
 *
 * Hephaistos (ergasterion/hephaistos) is itself an MCP server that loads
 * plugins (forge search/write/release, logs, memory, …) and serves them
 * over stdio or WSS. A product scaffolded by eidos can therefore expose
 * the whole hephaistos surface as its drop-in MCP surface — no raw node
 * server needed, just the borrowed drop-in wiring:
 *
 *   1. ports.env       <NAME>_PORT=<free-25xxx>
 *   2. pitchfork.toml  [daemons."<name>-mcp"]  run = "hephaistos --plugins=<…> --workspace=<target>"
 *   3. thresher config mcp_config.json http entry
 *   4. hephaistos.config.json per product (plugins + options)
 *   5. bunfig [env]    BUN_<NAME>_PORT
 *
 * Dry-run by default: prints the exact blocks to append. Use --write to apply.
 */
import { discoverDropins, infraDropins } from "../src/scaffold-services.ts";
import { suggestFreePort } from "./borrow-dropin.ts";

const PITCHFORK = "/home/toxic/pens/Pens/pitchfork.toml";
const THRESHER = "/home/toxic/pens/Pens/ranch/thresher/mcp_config.json";

export interface HephaistosDropinSpec {
  name: string;              // product name → <name>-mcp daemon
  target: string;            // product dir (workspace for hephaistos)
  plugins: string[];         // hephaistos plugin ids, e.g. ["forge","logs","memory"]
  port?: number;             // resolved free port if absent
  namespacePrefix?: string;  // MCP tool namespace prefix, default the product name
}

/** Next free port suggestion in the Pens 25xxx range, avoiding used ports. */
export function suggestFreePort(existing: number[] = []): number {
  const used = new Set(existing);
  for (let p = 25200; p < 25299; p++) if (!used.has(p)) return p;
  return 25999;
}

/** Borrowed ports.env stanza (R-301 owner-comment convention). */
export function portsEnvBlock(spec: HephaistosDropinSpec): string {
  return `# owner: ${spec.name} (${spec.name}-mcp hephaistos via eidos)\n${spec.name.toUpperCase()}_PORT=${spec.port}\n`;
}

/** Borrowed pitchfork monolith daemon stanza — runs hephaistos as the MCP server. */
export function pitchforkBlock(spec: HephaistosDropinSpec): string {
  const pluginsArg = spec.plugins.join(",");
  const nsArg = spec.namespacePrefix ?? spec.name;
  return [
    "",
    `[daemons."${spec.name}-mcp"]`,
    `run = "hephaistos --plugins=${pluginsArg} --workspace=${spec.target} --namespace-prefix=${nsArg}"`,
    'auto = ["start"]',
    "retry = true",
    "mise = true",
    `port = ${spec.port}`,
    `ready_http = "http://127.0.0.1:${spec.port}/mcp"`,
    "",
  ].join("\n");
}

/** Borrowed thresher mcp_config.json http entry (copy-an-existing verbatim rule). */
export function thresherBlock(spec: HephaistosDropinSpec): string {
  const pluginsArg = spec.plugins.join(",");
  const nsArg = spec.namespacePrefix ?? spec.name;
  return `{
  "name": "${spec.name}-mcp",
  "command": "hephaistos --plugins=${pluginsArg} --workspace=${spec.target} --namespace-prefix=${nsArg}",
  "protocol": "http",
  "url": "http://127.0.0.1:${spec.port}/mcp",
  "enabled": true,
  "timeout": 30
}`;
}

/** Borrowed hephaistos.config.json per product — pins the plugin set + options. */
export function hephaistosConfig(spec: HephaistosDropinSpec): string {
  const plugins: Record<string, unknown> = {};
  for (const p of spec.plugins) plugins[p] = {};
  return JSON.stringify(
    {
      plugins,
      namespacePrefix: spec.namespacePrefix ?? spec.name,
      corePrefix: spec.name,
    },
    null,
    2,
  );
}

/** Full borrowed drop-in plan for one hephaistos-backed product. */
export function borrowHephaistosDropinPlan(spec: HephaistosDropinSpec): {
  portsEnv: string; pitchfork: string; thresher: string; hephaistosConfig: string; envVars: string[];
} {
  const dropins = discoverDropins();
  const used = dropins.map((d) => d.port);
  // also avoid the ports the four infra tiers already claim
  const tierPorts = infraDropins().map((d) => d.port);
  const port = spec.port ?? suggestFreePort([...used, ...tierPorts]);
  const envVars = dropins
    .filter((d) => d.id === spec.name.toLowerCase())
    .map((d) => `${d.envVar}=${d.port}`);
  return {
    portsEnv: portsEnvBlock({ ...spec, port }),
    pitchfork: pitchforkBlock({ ...spec, port }),
    thresher: thresherBlock({ ...spec, port }),
    hephaistosConfig: hephaistosConfig(spec),
    envVars,
  };
}

const version = "1.0.0-hephaistos-dropin";
export { version, PITCHFORK, THRESHER };

/**
 * model-matrix-lib-dropin.ts — 5-lane model contract matrix as an eidos
 * drop-in library. ANY test can assert "same call, same behavior" across the
 * Pens's five provider families via the live router (rhodochrosite :25193).
 *
 * The five lanes (live ids verified 2026-10-30 from the router /v1/models):
 *   openai-family   — openai/gpt-oss-20b
 *   google-family   — google/diffusiongemma-26b-a4b-it
 *   deepseek-family — deepseek/deepseek-v4.1-flash-1017
 *   glm-family      — z-ai/glm-5.3-flash
 *   nvidia-family   — nvidia/llama-3.1-nemotron-safety-guard-8b-v3
 *
 * USAGE:
 *   import { modelMatrix } from "<eidos>/dropin/model-matrix-lib-dropin.ts";
 *   const mm = modelMatrix();
 *   const results = await mm.run(prompt, { timeoutMs: 25_000 });
 *   // results: { [family]: { ok, content?, err? } }
 *   expect(mm.allOk(results)).toBe(true);
 */
import { readFileSync } from "node:fs";
import { ok, err, type Result } from "neverthrow";

const ROUTER = "http://127.0.0.1:25193";
const KEY_FILE = "/home/toxic/.tau/rhodochrosite.key";

// BARE ids — the router's exec lane (anomaly #38: prefixed ids 404/ModelNotListed on
// completions; the /v1/models list is prefixed but completions want bare).
export const FIVE_LANES: Record<string, string> = {
	"openai-family": "gpt-oss-20b",
	"google-family": "diffusiongemma",
	"deepseek-family": "deepseek-v4.1-flash",
	"glm-family": "glm-5.3-flash",
	"nvidia-family": "nemotron-3.5-lightning",
};

export interface MatrixCell {
	ok: boolean;
	content?: string;
	err?: string;
	tokens?: number;
}

export interface MatrixResult {
	[family: string]: MatrixCell;
}

function readKey(): Result<string, Error> {
	try {
		const key = readFileSync(KEY_FILE, "utf8").trim();
		return key ? ok(key) : err(new Error("empty router key"));
	} catch (e) {
		return err(e instanceof Error ? e : new Error(String(e)));
	}
}

export function modelMatrix(opts: { router?: string; keyFile?: string } = {}) {
	const router = opts.router ?? ROUTER;
	return {
		id: "model-matrix-lib-dropin",
		version: "1.0.0",
		lanes: FIVE_LANES,

		/** Probe ONE model with ONE prompt. */
		async probe(
			model: string,
			prompt: string,
			probeOpts: { maxTokens?: number; timeoutMs?: number } = {},
		): Promise<Result<MatrixCell, Error>> {
			const key = readKey();
			if (key.isErr()) return err(key.error);
			const body = JSON.stringify({
				model,
				max_tokens: probeOpts.maxTokens ?? 120,
				messages: [{ role: "user", content: prompt }],
			});
			try {
				const res = await fetch(`${router}/v1/chat/completions`, {
					method: "POST",
					headers: { Authorization: `Bearer ${key.value}`, "Content-Type": "application/json" },
					body,
					signal: AbortSignal.timeout(probeOpts.timeoutMs ?? 25_000),
				});
				const d = (await res.json()) as {
					choices?: Array<{ message?: { content?: string } }>;
					usage?: { completion_tokens?: number };
				};
				const msg = d.choices?.[0]?.message ?? {};
				return ok({
					ok: true,
					content: (msg.content ?? "").slice(0, 200),
					tokens: d.usage?.completion_tokens,
				});
			} catch (e) {
				return ok({ ok: false, err: String(e instanceof Error ? e.message : e).slice(0, 120) });
			}
		},

		/** Run the SAME prompt across all five lanes. */
		async run(
			prompt: string,
			runOpts: { maxTokens?: number; timeoutMs?: number; lanes?: string[] } = {},
		): Promise<Result<MatrixResult, Error>> {
			const key = readKey();
			if (key.isErr()) return err(key.error);
			const lanes = runOpts.lanes ?? Object.keys(FIVE_LANES);
			const out: MatrixResult = {};
			const settled = await Promise.allSettled(
				lanes.map((fam) => this.probe(FIVE_LANES[fam]!, prompt, runOpts)),
			);
			lanes.forEach((fam, i) => {
				const s = settled[i]!;
				if (s.status === "fulfilled" && s.value.isOk()) out[fam] = s.value.value;
				else out[fam] = { ok: false, err: "probe failed" };
			});
			return ok(out);
		},

		/** All lanes behaved (returned a cell with ok=true). */
		allOk(results: MatrixResult): boolean {
			return Object.values(results).every((c) => c.ok);
		},
	};
}

/**
 * rig-skills-lib-dropin.ts — ring's specialized-agent skills as eidos
 * knowledge drop-ins.
 *
 * ring (LerianStudio) ships 89 skills + 38 agents enforcing engineering
 * practices. This drop-in borrows the SKILL INDEX shape: a registry of
 * { id, trigger, summary } that consumers (kleio detectors, tau skills,
 * hephaistos plugins) consult when a failure-family fires.
 */
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { ok, err, type Result } from "neverthrow";

const RING = "/home/toxic/pens/ranch/products/ring";

export interface RigSkill {
	id: string;
	path: string;
	summary: string;
	trigger?: string;
}

/** Index ring's skills (the default/ team's SKILL.md files). */
export function indexRigSkills(
	root: string = join(RING, "default"),
): Result<RigSkill[], Error> {
	if (!existsSync(root)) {
		return err(new Error(`ring skills root missing: ${root}`));
	}
	const skills: RigSkill[] = [];
	function walk(dir: string, depth: number): void {
		if (depth > 4) return;
		let entries;
		try {
			entries = readdirSync(dir, { withFileTypes: true });
		} catch {
			return;
		}
		for (const e of entries) {
			const p = join(dir, e.name);
			if (e.isDirectory()) walk(p, depth + 1);
			else if (e.name === "SKILL.md") {
				try {
					const c = readFileSync(p, "utf8");
					const summary =
						c.match(/^summary:\s*(.+)$/m)?.[1] ??
						c.split("\n").filter((l) => l.trim() && !l.startsWith("#") && !l.startsWith("---"))[0] ??
						e.name;
					const trigger = c.match(/^trigger:\s*(.+)$/m)?.[1];
					skills.push({ id: e.name.replace(/\.md$/, ""), path: p, summary: summary.slice(0, 160), trigger });
				} catch {}
			}
		}
	}
	walk(root, 0);
	return ok(skills);
}

/** Match a failure/need to the best ring skill (simple trigger-substring rank). */
export function matchRigSkill(
	query: string,
	skills?: RigSkill[],
): Result<RigSkill | null, Error> {
	const list = skills ?? indexRigSkills().unwrapOr([]);
	let best: RigSkill | null = null;
	let bestScore = 0;
	for (const s of list) {
		const hay = `${s.id} ${s.trigger ?? ""} ${s.summary}`.toLowerCase();
		let score = 0;
		for (const word of query.toLowerCase().split(/\W+/).filter((w) => w.length > 3)) {
			if (hay.includes(word)) score++;
		}
		if (score > bestScore) {
			bestScore = score;
			best = s;
		}
	}
	return ok(best);
}

