/**
 * rust-fast-build-lib-dropin.ts — apply the Pens's fast Rust build profile
 * to a target Cargo.toml. Pattern-borrowed from the rhodochrosite proxy build
 * (verified live 2026-11-02: cold 6m10s, incremental 40s with mold vs the old
 * fat-LTO single-codegen-unit 2-5min lock; cc 1.2.65 -> 1.11.0 fixed the
 * sccache-wrapped cc jobserver hang).
 *
 * Capability: ensure `[profile.release-fast]` exists in a Rust project.
 * Idempotent: skips when the profile is already present. Monadic (neverthrow,
 * the scaffold default).
 *
 * Usage (as a drop-in, no wiring):
 *   import { applyRustFastBuild } from "./rust-fast-build-lib-dropin.ts";
 *   const r = await applyRustFastBuild("/path/to/project");
 *   r.match({ ok: (s) => console.log(s), err: (e) => console.error(e.message) });
 */
import { err, ok, type Result } from "neverthrow";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

/** The committed template = the verified rhodochrosite proxy fast profile. */
export const RUST_FAST_BUILD_TEMPLATE = `# eidos rust-fast-build drop-in — Pens fast-iteration profile (verified 2026-11-02).
# Thin LTO + 8 codegen units + opt-level=2: the iteration loop (~40s incremental
# with mold) instead of the fat-LTO single-unit 2-5min lock. The final deploy
# binary stays under [profile.release]; release-fast is for daily loops.
[profile.release-fast]
inherits = "release"
lto = "thin"
codegen-units = 8
opt-level = 2
`;

/**
 * Append the release-fast profile to <dir>/Cargo.toml if absent.
 * - No Cargo.toml -> Ok("skip") (not a Rust project; callers decide).
 * - Profile already present -> Ok("noop") (idempotent).
 * - Otherwise appends and returns Ok("applied").
 */
export function applyRustFastBuild(dir: string): Result<"skip" | "noop" | "applied", Error> {
  const cargoPath = join(dir, "Cargo.toml");
  if (!existsSync(cargoPath)) return ok("skip");
  let text: string;
  try {
    text = readFileSync(cargoPath, "utf8");
  } catch (e) {
    return err(e instanceof Error ? e : new Error(String(e)));
  }
  if (text.includes("[profile.release-fast]")) return ok("noop");
  // Append at the end; the profile block is top-level (never inside a package).
  const updated = `${text.replace(/\s*$/, "\n")}\n${RUST_FAST_BUILD_TEMPLATE}`;
  try {
    writeFileSync(cargoPath, updated);
  } catch (e) {
    return err(e instanceof Error ? e : new Error(String(e)));
  }
  return ok("applied");
}

/**
 * tdd-adapter-lib-dropin.ts — devloop's hook-payload adapter as an eidos
 * drop-in library (Bun-native, verbatim shape borrow).
 *
 * devloop (compforge) ships the PreToolUse/PostToolUse hook contract:
 *   HookPayload { hook_event_name, tool_name, tool_input, cwd, session_id }
 *   preToolDecision(payload) → { hookSpecificOutput, systemMessage } | {}
 * Borrowed so eidos-parented products share ONE hook payload shape with the
 * devloop eval loop.
 */
export interface HookPayload {
	readonly hook_event_name?: unknown;
	readonly tool_name?: unknown;
	readonly tool_input?: unknown;
	readonly tool_response?: unknown;
	readonly cwd?: unknown;
	readonly session_id?: unknown;
	readonly model?: unknown;
	readonly [key: string]: unknown;
}

export interface HookHarness {
	readonly harness: "devloop" | "claude" | "codex";
}

export interface HookDecision {
	hookSpecificOutput?: {
		hookEventName: "PreToolUse" | "PostToolUse";
		permissionDecision?: "deny" | "allow" | "ask";
		permissionDecisionReason?: string;
	};
	systemMessage?: string;
}

/** Normalize a raw payload into a typed tool-input record (devloop semantics). */
export function normalizeToolInput(payload: HookPayload): Record<string, unknown> {
	const rawInput = payload.tool_input;
	const toolInput: Record<string, unknown> =
		rawInput !== null && typeof rawInput === "object" && !Array.isArray(rawInput)
			? { ...(rawInput as Record<string, unknown>) }
			: { input: String(rawInput ?? "") };
	if (typeof payload.session_id === "string") toolInput.session_id = payload.session_id;
	return toolInput;
}

/** PostToolUse error detection (the reactive-error plugin's feed). */
export function isToolError(payload: HookPayload): boolean {
	const resp = payload.tool_response;
	if (typeof resp === "string") return /error|denied|aborted|fail/i.test(resp);
	if (resp && typeof resp === "object") {
		const r = resp as Record<string, unknown>;
		return r.error !== undefined || r.isError === true;
	}
	return false;
}

/**
 * tdd-gate-lib-dropin.ts — night-market's TDD/BDD Iron-Law gate, ported to
 * Bun/TS as an eidos drop-in library.
 *
 * The Iron Law: NO IMPLEMENTATION WITHOUT A FAILING TEST FIRST.
 * Borrowed from claude-night-market/plugins/imbue/hooks/tdd_bdd_gate.py
 * (python → TS). Given a Write/Edit target path, decides whether the write
 * is gated: implementation files require a co-located failing test.
 *
 * USAGE:
 *   import { tddGate } from "<eidos>/dropin/tdd-gate-lib-dropin.ts";
 *   const verdict = tddGate({ path: "src/feature.ts", op: "write" });
 *   if (verison.blocked) writeTestFirst(verison.reason);
 */
import { existsSync } from "node:fs";
import { ok, err, type Result } from "neverthrow";

export interface GateVerdict {
	blocked: boolean;
	reason: string;
	implPath: string;
	testPath?: string;
	kind: "impl" | "test" | "non-code" | "docs";
}

const IMPL_RE = /\.(ts|tsx|js|mjs|py)$/;
const TEST_RE = /(\.test\.|_test\.|\.spec\.|_spec\.|\/tests?\/)/;

/** Co-located test-path candidates for an implementation file. */
export function testCandidatesFor(implPath: string): string[] {
	const base = implPath.replace(/\.(ts|tsx|js|mjs|py)$/, "");
	return [
		base.replace(/\/src\//, "/test/") + ".test.ts",
		base + ".test.ts",
		base + "_test.ts",
		base.replace(/\/src\//, "/tests/") + ".spec.ts",
		base + ".spec.ts",
	];
}

export function tddGate(input: {
	path: string;
	op: "write" | "edit";
	hasFailingTest?: boolean;
}): Result<GateVerdict, Error> {
	const { path, op, hasFailingTest } = input;
	if (!path) return err(new Error("path required"));

	// docs / non-code are never gated
	if (!IMPL_RE.test(path)) {
		return ok({ blocked: false, reason: "non-code — not gated", implPath: path, kind: "non-code" });
	}
	// test files themselves are never gated (they ARE the red)
	if (TEST_RE.test(path) || /\/tests?\//.test(path)) {
		return ok({ blocked: false, reason: "test file — the red itself", implPath: path, kind: "test" });
	}

	// find a co-located test
	const candidates = testCandidatesFor(path);
	const testPath = candidates.find((c) => existsSync(c));
	if (!testPath) {
		return ok({
			blocked: true,
			reason: `IRON LAW: no failing test exists for ${path}. Write the test FIRST (red), then implement (green). Candidates tried: ${candidates.slice(0, 2).join(", ")}`,
			implPath: path,
			kind: "impl",
		});
	}

	if (hasFailingTest === false) {
		return ok({
			blocked: true,
			reason: `IRON LAW: test ${testPath} exists but is not failing — write a NEW failing test for the change first.`,
			implPath: path,
			testPath,
			kind: "impl",
		});
	}

	return ok({
		blocked: false,
		reason: `test-first satisfied (${testPath})`,
		implPath: path,
		testPath,
		kind: "impl",
	});
}

/**
 * trio-lib-dropin.ts — the trio code-intelligence engine as a portable
 * eidos drop-in library.
 *
 * Trio lives at @geode/triphylite (pens/geode/products/triphylite). This
 * drop-in wraps its five-channel engine behind the eidos drop-in contract:
 *   - discoverable (ports.env / package.json probing)
 *   - monadic results (neverthrow — the scaffold default drop-in)
 *   - consumer-agnostic: any geode mineral (ffs-diff, kleio, coreelec-mcp)
 *     borrows this and gets AST+BM25+LSP+ROUTE fused search with zero engine
 *     wiring.
 *
 * USAGE (in a consumer):
 *   import { borrowTrio } from "<eidos>/dropin/trio-lib-dropin.ts";
 *   const trio = borrowTrio(import.meta.url);   // engine resolved relative to consumer
 *   const res = await trio.search("playback.media", { root: "/some/dir", limit: 5 });
 *   res.match({ ok: (r) => use(r.hits), err: (e) => log(e.message) });
 */
import { ok, err, type Result } from "neverthrow";

const TRIPHYLITE = "/home/toxic/pens/geode/products/triphylite/src/engine.ts";

export interface TrioSearchOpts {
	root?: string;
	limit?: number;
	/** Restrict to a single channel: "ast" | "bm25" | "lsp" | "route" | "all" */
	channel?: "ast" | "bm25" | "lsp" | "route" | "all";
}

export interface TrioFusedHit {
	file: string;
	line: number;
	snippet: string;
	channels: string[];
	rrfScore: number;
}

export interface TrioSearchResult {
	hits: TrioFusedHit[];
	stats: { ast: number; bm25: number; lsp: number; route: number; elapsedMs: number };
}

type TrioEngine = {
	searchRoutes: (
		dir: string,
		mode: string,
		limit?: number,
	) => Promise<Array<{ file: string; line: number; snippet: string; source: string; score: number }>>;
	executeReadTrioAudit: (
		query: string,
		targetDir?: string,
		limit?: number,
	) => Promise<{
		hits: Array<{ file: string; line: number; snippet: string; rrfScore: number; channels: string[] }>;
		stats: { ast: number; bm25: number; lsp: number; route: number; elapsedMs: number };
	}>;
};

/** Engine module loader — dynamic import keeps consumers decoupled from the engine path at type level. */
async function loadEngine(): Promise<Result<TrioEngine, Error>> {
	try {
		const mod = (await import(TRIPHYLITE)) as unknown as TrioEngine;
		return ok(mod);
	} catch (e) {
		return err(e instanceof Error ? e : new Error(String(e)));
	}
}

/** Borrow the trio engine as a monadic drop-in library. */
export function borrowTrio(_consumerUrl?: string) {
	return {
		id: "trio-lib-dropin",
		version: "1.0.0",
		engine: TRIPHYLITE,

		/** Fused search across all (or one) trio channels. */
		async search(
			query: string,
			opts: TrioSearchOpts = {},
		): Promise<Result<TrioSearchResult, Error>> {
			if (!query.trim()) return err(new Error("query required"));
			const mod = await loadEngine();
			if (mod.isErr()) return err(mod.error);

			const root = opts.root ?? ".";
			const limit = opts.limit ?? 20;
			const channel = opts.channel ?? "all";

			try {
				if (channel === "route") {
					const routeHits = await mod.value.searchRoutes(root, query, limit);
					return ok({
						hits: routeHits.map((h) => ({
							file: h.file, line: h.line, snippet: h.snippet,
							channels: ["route"], rrfScore: h.score,
						})),
						stats: { ast: 0, bm25: 0, lsp: 0, route: routeHits.length, elapsedMs: 0 },
					});
				}
				const fused = await mod.value.executeReadTrioAudit(query, root, limit);
				return ok({
					hits: fused.hits.map((h) => ({
						file: h.file, line: h.line, snippet: h.snippet,
						channels: [...h.channels], rrfScore: h.rrfScore,
					})),
					stats: fused.stats,
				});
			} catch (e) {
				return err(e instanceof Error ? e : new Error(String(e)));
			}
		},
	};
}

